import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { ROLES } from '../utils/roles';
import ProtectedRoute from '../components/ProtectedRoute';
import RoleRoute from '../components/RoleRoute';
import Navbar from '../components/Navbar';
import Sidebar from '../components/Sidebar';

// Auth Pages
import LoginPage from '../pages/Auth/LoginPage';
import RegisterPage from '../pages/Auth/RegisterPage';

// Admin Pages
import AdminDashboard from '../pages/Admin/AdminDashboard';
import RegisterDoctor from '../pages/Admin/RegisterDoctor';
import RegisterReceptionist from '../pages/Admin/RegisterReceptionist';
import ListDoctors from '../pages/Admin/ListDoctors';
import ListReceptionists from '../pages/Admin/ListReceptionists';

// Receptionist Pages
import ReceptionistDashboard from '../pages/Receptionist/ReceptionistDashboard';
import RegisterPatient from '../pages/Receptionist/RegisterPatient';
import BookAppointment from '../pages/Receptionist/BookAppointment';
import AppointmentSuccess from '../pages/Receptionist/AppointmentSuccess';

// Doctor Pages
import DoctorDashboard from '../pages/Doctor/DoctorDashboard';
import AppointmentDetails from '../pages/Doctor/AppointmentDetails';
import CreatePrescription from '../pages/Doctor/CreatePrescription';

// Patient Pages
import PatientDashboard from '../pages/Patient/PatientDashboard';
import MyAppointments from '../pages/Patient/MyAppointments';
import MyPrescriptions from '../pages/Patient/MyPrescriptions';
import QRPrescriptionView from '../pages/Patient/QRPrescriptionView';

const AppRouter = () => {
  const { isAuthenticated, user } = useAuth();

  const Layout = ({ children }) => {
    if (!isAuthenticated) {
      return children;
    }

    return (
      <div className="flex">
        <Sidebar role={user?.role} />
        <div className="flex-1 flex flex-col">
          <Navbar />
          <main className="flex-1 bg-gray-100">{children}</main>
        </div>
      </div>
    );
  };

  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route path="/register" element={<RegisterPage />} />
      
      <Route
        path="/admin/dashboard"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.ADMIN]}>
              <AdminDashboard />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/admin/register-doctor"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.ADMIN]}>
              <RegisterDoctor />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/admin/register-receptionist"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.ADMIN]}>
              <RegisterReceptionist />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/admin/doctors"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.ADMIN]}>
              <ListDoctors />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/admin/receptionists"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.ADMIN]}>
              <ListReceptionists />
            </RoleRoute>
          </Layout>
        }
      />

      <Route
        path="/receptionist/dashboard"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.RECEPTIONIST]}>
              <ReceptionistDashboard />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/receptionist/register-patient"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.RECEPTIONIST]}>
              <RegisterPatient />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/receptionist/book-appointment"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.RECEPTIONIST]}>
              <BookAppointment />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/receptionist/appointment-success"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.RECEPTIONIST]}>
              <AppointmentSuccess />
            </RoleRoute>
          </Layout>
        }
      />

      <Route
        path="/doctor/dashboard"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.DOCTOR]}>
              <DoctorDashboard />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/doctor/appointment/:id"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.DOCTOR]}>
              <AppointmentDetails />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/doctor/prescription/:appointmentId"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.DOCTOR]}>
              <CreatePrescription />
            </RoleRoute>
          </Layout>
        }
      />

      <Route
        path="/patient/dashboard"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.PATIENT]}>
              <PatientDashboard />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/patient/appointments"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.PATIENT]}>
              <MyAppointments />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/patient/prescriptions"
        element={
          <Layout>
            <RoleRoute allowedRoles={[ROLES.PATIENT]}>
              <MyPrescriptions />
            </RoleRoute>
          </Layout>
        }
      />
      <Route
        path="/patient/prescriptions/qr/:token"
        element={<QRPrescriptionView />}
      />

      <Route path="/" element={<Navigate to="/login" replace />} />
      <Route path="*" element={<Navigate to="/login" replace />} />
    </Routes>
  );
};

export default AppRouter;
